-- ② 24 个「后端有能力、ops-web 没有入口」的码。
--    判权读库：没有功能点 = 这个码授不出去 = 本该有权限的岗位静默失权
--    （FINANCE 会拿不到 finance:payout:execute）。所以它们必须在库里存在，
--    以 ACTION 点的形态（无 href），与已有的 10 个页面内动作点同一种。

-- 重建角色×功能点。整表重建而不是增量补 —— 换码之后哪些该授哪些不该授全变了，
-- 增量改法要枚举「原来给了现在不该给」的组合，那比重算更容易错。
-- ⚠️ 只重建预置角色；自定义角色（builtin=0）的授权是人配的，不能覆盖。
DELETE FROM sys_role_point WHERE end_code = 'OPS' AND role_code IN ('SUPER_ADMIN', 'BD', 'GOODS_OPS', 'SUPPORT', 'CAMPAIGN_OPS', 'COMMUNITY_OPS', 'AUDITOR', 'FINANCE', 'RISK', 'ANALYST', 'TECH_OPS');
